with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'التنبؤ العددي المتقدم وتشغيل النماذج الجوية','تهيئة المشاهدات واستيعاب البيانات والشروط الحدية والفيزياء العددية وتشغيل النماذج والتحقق من مخرجاتها.',30,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تهيئة البيانات وتشغيل النماذج',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التحقق والتشخيص وتحسين التوقع',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('nwp-observation-preprocessing','تهيئة مشاهدات الأرصاد للنماذج العددية','فحص الرصد وتجميعه وضبط جودته قبل إدخاله في دورة التنبؤ.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس تهيئة مشاهدات الأرصاد للنماذج العددية ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: فحص الرصد وتجميعه وضبط جودته قبل إدخاله في دورة التنبؤ. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو فحص الرصد، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو التجانس الزمني والمكاني من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو توثيق البيانات باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2360,65,'["فحص الرصد","التجانس الزمني والمكاني","توثيق البيانات"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-data-assimilation-overview','مبادئ استيعاب البيانات في النماذج العددية','تحويل المشاهدات إلى تحليل ابتدائي متسق مع النموذج.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس مبادئ استيعاب البيانات في النماذج العددية ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: تحويل المشاهدات إلى تحليل ابتدائي متسق مع النموذج. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو شرح دور الاستيعاب، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تمييز مصادر الرصد من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو فهم حالات عدم اليقين باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2370,65,'["شرح دور الاستيعاب","تمييز مصادر الرصد","فهم حالات عدم اليقين"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-background-error-covariance','أخطاء الخلفية والارتباطات في الاستيعاب','فهم مصفوفات الخطأ وتأثيرها في التحليل الابتدائي.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس أخطاء الخلفية والارتباطات في الاستيعاب ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: فهم مصفوفات الخطأ وتأثيرها في التحليل الابتدائي. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو تعريف خطأ الخلفية، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو فهم الارتباطات من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو قراءة أثر الضبط باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2380,65,'["تعريف خطأ الخلفية","فهم الارتباطات","قراءة أثر الضبط"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-3dvar-4dvar-ensemble-kalman','مقارنة 3D-Var و4D-Var ومرشح كالمان التجميعي','مقارنة الأطر الأساسية لاستيعاب البيانات.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس مقارنة 3D-Var و4D-Var ومرشح كالمان التجميعي ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: مقارنة الأطر الأساسية لاستيعاب البيانات. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو تمييز الصيغ، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو مقارنة الاستفادة الزمنية من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو فهم المتطلبات الحسابية باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2390,65,'["تمييز الصيغ","مقارنة الاستفادة الزمنية","فهم المتطلبات الحسابية"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-boundary-initial-conditions','الشروط الابتدائية والحدية للنماذج الإقليمية','إعداد مجال النموذج وشروطه الخارجية والداخلية.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس الشروط الابتدائية والحدية للنماذج الإقليمية ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: إعداد مجال النموذج وشروطه الخارجية والداخلية. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو اختيار المجال، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تحديد الشروط الحدية من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو فهم تأثير الحواف باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2400,65,'["اختيار المجال","تحديد الشروط الحدية","فهم تأثير الحواف"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-nesting-domain-resolution','تداخل المجالات ودقة الشبكة العددية','تصميم المجالات المتداخلة وموازنة الدقة والكلفة.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس تداخل المجالات ودقة الشبكة العددية ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: تصميم المجالات المتداخلة وموازنة الدقة والكلفة. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو اختيار الدقة، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تصميم التداخل من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو تقييم كلفة التشغيل باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2410,65,'["اختيار الدقة","تصميم التداخل","تقييم كلفة التشغيل"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-physical-parameterizations','المخططات الفيزيائية في النماذج الجوية','فهم تمثيل السحب والإشعاع والسطح والطبقة الحدية.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس المخططات الفيزيائية في النماذج الجوية ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: فهم تمثيل السحب والإشعاع والسطح والطبقة الحدية. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو تصنيف المخططات، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو فهم حدود التمثيل من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو مقارنة الحساسية باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2420,65,'["تصنيف المخططات","فهم حدود التمثيل","مقارنة الحساسية"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-land-surface-models','نماذج سطح الأرض والتربة والغطاء النباتي','دور خصائص السطح ورطوبة التربة في التنبؤ.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس نماذج سطح الأرض والتربة والغطاء النباتي ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: دور خصائص السطح ورطوبة التربة في التنبؤ. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو تحديد متغيرات السطح، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو فهم تدفق الطاقة من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو تقييم أثر رطوبة التربة باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2430,65,'["تحديد متغيرات السطح","فهم تدفق الطاقة","تقييم أثر رطوبة التربة"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-cloud-microphysics','فيزياء السحب الدقيقة والهطول في النماذج','تمثيل الماء السائل والجليد والهطول وتوزيعه.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس فيزياء السحب الدقيقة والهطول في النماذج ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: تمثيل الماء السائل والجليد والهطول وتوزيعه. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو شرح فئات الهيدرو ميتور، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تمييز المخططات من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو فهم حساسية الهطول باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2440,65,'["شرح فئات الهيدرو ميتور","تمييز المخططات","فهم حساسية الهطول"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-boundary-layer-turbulence','الطبقة الحدية والاضطراب والخلط الرأسي','تحليل الخلط والاحتكاك والتدفقات السطحية.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس الطبقة الحدية والاضطراب والخلط الرأسي ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: تحليل الخلط والاحتكاك والتدفقات السطحية. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو شرح بنية الطبقة الحدية، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو فهم الخلط من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو تقييم الرياح والحرارة قرب السطح باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2450,65,'["شرح بنية الطبقة الحدية","فهم الخلط","تقييم الرياح والحرارة قرب السطح"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-radiation-schemes','المخططات الإشعاعية والتفاعل مع السحب','دور الإشعاع الشمسي والأرضي في ميزانية الطاقة.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس المخططات الإشعاعية والتفاعل مع السحب ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: دور الإشعاع الشمسي والأرضي في ميزانية الطاقة. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو تمييز الإشعاع القصير والطويل، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو فهم أثر السحب من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو تحليل التسخين اليومي باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2460,65,'["تمييز الإشعاع القصير والطويل","فهم أثر السحب","تحليل التسخين اليومي"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-cumulus-convection','تمثيل الحمل العميق والضحل في النماذج','متى تستخدم مخططات الحمل وكيف تؤثر في الهطول.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس تمثيل الحمل العميق والضحل في النماذج ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: متى تستخدم مخططات الحمل وكيف تؤثر في الهطول. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو شرح الحمل، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تمييز الحمل الممثل صراحة من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو فهم حساسية التنبؤ باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2470,65,'["شرح الحمل","تمييز الحمل الممثل صراحة","فهم حساسية التنبؤ"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-model-cycling-and-scheduling','دورة تشغيل النموذج وجدولة المهام','تنظيم جلب البيانات والتهيئة والتشغيل وما بعد المعالجة.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس دورة تشغيل النموذج وجدولة المهام ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: تنظيم جلب البيانات والتهيئة والتشغيل وما بعد المعالجة. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو رسم دورة التشغيل، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تحديد الاعتماديات من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو إدارة التأخير باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2480,65,'["رسم دورة التشغيل","تحديد الاعتماديات","إدارة التأخير"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-parallel-computing-basics','الحوسبة المتوازية وتشغيل النماذج عالية الدقة','مفاهيم تقسيم المجال والموارد والحوسبة.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس الحوسبة المتوازية وتشغيل النماذج عالية الدقة ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: مفاهيم تقسيم المجال والموارد والحوسبة. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو شرح MPI بصورة مفاهيمية، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو فهم توزيع الحمل من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو تقدير الموارد باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2490,65,'["شرح MPI بصورة مفاهيمية","فهم توزيع الحمل","تقدير الموارد"]','تهيئة البيانات وتشغيل النماذج'),
('nwp-postprocessing-gridded-fields','معالجة حقول النماذج وإنتاج الشبكات','قراءة الحقول وتحويلها وإنتاج منتجات قابلة للاستخدام.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس معالجة حقول النماذج وإنتاج الشبكات ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: قراءة الحقول وتحويلها وإنتاج منتجات قابلة للاستخدام. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو فهم صيغ الحقول، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو توحيد الشبكات من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو إعداد منتجات مكانية باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2500,65,'["فهم صيغ الحقول","توحيد الشبكات","إعداد منتجات مكانية"]','التحقق والتشخيص وتحسين التوقع'),
('nwp-interpolation-regridding','الاستيفاء وإعادة الإسقاط بين الشبكات','اختيار طرق الاستيفاء وإدراك أثرها في القيم.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس الاستيفاء وإعادة الإسقاط بين الشبكات ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: اختيار طرق الاستيفاء وإدراك أثرها في القيم. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو تمييز طرق الاستيفاء، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو اختيار الطريقة المناسبة من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو تقييم أثر التحويل باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2510,65,'["تمييز طرق الاستيفاء","اختيار الطريقة المناسبة","تقييم أثر التحويل"]','التحقق والتشخيص وتحسين التوقع'),
('nwp-model-verification-methods','طرق التحقق من التنبؤات العددية','مقاييس التحيز والخطأ والارتباط والمهارة.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس طرق التحقق من التنبؤات العددية ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: مقاييس التحيز والخطأ والارتباط والمهارة. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو حساب مقاييس أساسية، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تمييز التحقق النقطي والمكاني من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو قراءة النتائج باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2520,65,'["حساب مقاييس أساسية","تمييز التحقق النقطي والمكاني","قراءة النتائج"]','التحقق والتشخيص وتحسين التوقع'),
('nwp-object-based-verification','التحقق المكاني القائم على الأجسام والأنماط','تقييم موقع الظواهر وشكلها وتوقيتها بدلاً من النقاط فقط.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس التحقق المكاني القائم على الأجسام والأنماط ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: تقييم موقع الظواهر وشكلها وتوقيتها بدلاً من النقاط فقط. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو شرح مشكلة الإزاحة، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تقييم الأجسام من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو مقارنة الأنماط باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2530,65,'["شرح مشكلة الإزاحة","تقييم الأجسام","مقارنة الأنماط"]','التحقق والتشخيص وتحسين التوقع'),
('nwp-ensemble-spread-calibration','انتشار المجموعة والمعايرة الاحتمالية','تفسير انتشار الأعضاء ومعايرة الاحتمالات.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس انتشار المجموعة والمعايرة الاحتمالية ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: تفسير انتشار الأعضاء ومعايرة الاحتمالات. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو شرح الانتشار، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تمييز المعايرة من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو تقييم موثوقية الاحتمالات باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2540,65,'["شرح الانتشار","تمييز المعايرة","تقييم موثوقية الاحتمالات"]','التحقق والتشخيص وتحسين التوقع'),
('nwp-operational-model-incident-review','مراجعة أعطال دورة التنبؤ واستمرارية التشغيل','تشخيص فشل المهام وتأخر البيانات واستعادة الخدمة.','{"blocks":[{"type":"text","text":"يتناول هذا الدرس مراجعة أعطال دورة التنبؤ واستمرارية التشغيل ضمن سلسلة تشغيل التنبؤ العددي، مع التركيز على الأساس العلمي والقرار التشغيلي."},{"type":"text","text":"المفهوم الأساسي: تشخيص فشل المهام وتأخر البيانات واستعادة الخدمة. ويجب فهمه ضمن ترابط الحالة الابتدائية والفيزياء العددية والبيانات."},{"type":"text","text":"الهدف الأول هو تصنيف الأعطال، وذلك بتحديد المصطلحات والمتغيرات والافتراضات التي يقوم عليها الإجراء."},{"type":"text","text":"الهدف الثاني هو تحديد نقاط المراقبة من خلال مقارنة الخيارات وبيان أثر كل خيار على تمثيل الغلاف الجوي."},{"type":"text","text":"الهدف الثالث هو توثيق مراجعة ما بعد الحادث باستخدام بيانات مرجعية وفحوص جودة قابلة للتكرار."},{"type":"text","text":"تبدأ الممارسة بتحديد مجال الدراسة والفترة الزمنية ومصادر البيانات وإصدارات النموذج والتهيئة المستخدمة."},{"type":"text","text":"يجب الاحتفاظ ببيانات وصفية تشمل الوحدات والإحداثيات والتوقيت ومصدر الحقل وإصدار المعالجة."},{"type":"text","text":"تُفحص النتائج بحثاً عن القيم المفقودة والانحرافات غير المعتادة وعدم الاتساق المكاني أو الزمني."},{"type":"text","text":"تقارن المخرجات بمرجع مستقل أو دورة سابقة مع الانتباه إلى اختلاف الدقة والتمثيل وعدم اليقين."},{"type":"text","text":"توثق القيود والافتراضات وأسباب اختيار الإعداد حتى يمكن إعادة التجربة ومراجعة القرار."},{"type":"text","text":"مثال تطبيقي: إعداد تجربة مقارنة بين إعدادين مع تثبيت بقية العوامل ثم تقييم أثر التغيير على المتغير المستهدف."},{"type":"callout","text":"الخلاصة: لا يعتمد الحكم على نموذج أو إعداد على مظهر خريطة واحدة، بل على تشخيص موثق وتحقق متعدد المقاييس."}]}',2550,65,'["تصنيف الأعطال","تحديد نقاط المراقبة","توثيق مراجعة ما بعد الحادث"]','التحقق والتشخيص وتحسين التوقع'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'تهيئة البيانات وتشغيل النماذج' then u1.id else u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'التنبؤ العددي المتقدم وتشغيل النماذج الجوية',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;